python3 - <<'EOF'
import xml.etree.ElementTree as ET

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-hitl-multi-outcome-routing/LeaveRequestBpmn/LeaveRequestBpmn.bpmn')
root = tree.getroot()

errors = []

# 1. Root is definitions with correct namespaces
assert root.tag == '{http://www.omg.org/spec/BPMN/20100524/MODEL}definitions', "Root tag wrong"

# 2. Collect all element ids in process
process = root.find('bpmn:process', NS)
all_ids = {}
def collect_ids(el):
    eid = el.get('id')
    if eid:
        all_ids[eid] = el.tag
    for child in el:
        collect_ids(child)
collect_ids(root)
print("All IDs:", list(all_ids.keys()))

# 3. Collect sequence flows
flows = process.findall('bpmn:sequenceFlow', NS)
flow_ids = {f.get('id') for f in flows}
print("Flow IDs:", flow_ids)

# sourceRef / targetRef resolve
for f in flows:
    src = f.get('sourceRef')
    tgt = f.get('targetRef')
    if src not in all_ids:
        errors.append(f"Flow {f.get('id')}: sourceRef {src} not found")
    if tgt not in all_ids:
        errors.append(f"Flow {f.get('id')}: targetRef {tgt} not found")

# 4. Exclusive gateway: non-default flows have conditions; exactly one default
gws = process.findall('bpmn:exclusiveGateway', NS)
for gw in gws:
    default_flow = gw.get('default')
    print(f"Gateway {gw.get('id')} default={default_flow}")
    outgoing = [o.text for o in gw.findall('bpmn:outgoing', NS)]
    print(f"  Outgoing: {outgoing}")
    for flow_id in outgoing:
        if flow_id == default_flow:
            # default flow should have no condition
            flow_el = process.find(f"bpmn:sequenceFlow[@id='{flow_id}']", NS)
            cond = flow_el.find('bpmn:conditionExpression', NS) if flow_el is not None else None
            if cond is not None:
                errors.append(f"Default flow {flow_id} has a conditionExpression - should not")
        else:
            flow_el = process.find(f"bpmn:sequenceFlow[@id='{flow_id}']", NS)
            cond = flow_el.find('bpmn:conditionExpression', NS) if flow_el is not None else None
            if cond is None:
                errors.append(f"Non-default flow {flow_id} of gateway {gw.get('id')} missing conditionExpression")
            else:
                print(f"  Flow {flow_id} condition: {cond.text}")

# 5. No activity/event has more than one incoming flow
for el in process:
    incoming = el.findall('bpmn:incoming', NS)
    if len(incoming) > 1:
        errors.append(f"Element {el.get('id')} has multiple incoming flows: {[i.text for i in incoming]}")

# 6. Diagram: shapes and edges
diagram = root.find('bpmndi:BPMNDiagram', NS)
plane = diagram.find('bpmndi:BPMNPlane', NS)
shape_elements = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', NS)}
edge_elements = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', NS)}
print("Shapes:", shape_elements)
print("Edges:", edge_elements)

# Every node (non-sequenceFlow process flowElement) needs a shape
node_tags = {
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}startEvent',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}endEvent',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}userTask',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}task',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}exclusiveGateway',
}
for el in process:
    if el.tag in node_tags:
        eid = el.get('id')
        if eid not in shape_elements:
            errors.append(f"Node {eid} ({el.tag}) missing BPMNShape")

# Every flow needs an edge
for flow_id in flow_ids:
    if flow_id not in edge_elements:
        errors.append(f"Flow {flow_id} missing BPMNEdge")

# 7. vars references in conditions resolve to declared variables
var_ids = set()
variables_el = process.find('bpmn:extensionElements/uipath:variables', NS)
if variables_el is not None:
    for v in variables_el:
        var_ids.add(v.get('id'))
print("Declared var IDs:", var_ids)

import re
for f in flows:
    cond = f.find('bpmn:conditionExpression', NS)
    if cond is not None and cond.text:
        refs = re.findall(r'vars\.(\w+)', cond.text)
        for ref in refs:
            if ref not in var_ids:
                errors.append(f"Flow {f.get('id')} condition references undeclared var {ref}")

if errors:
    print("\nERRORS:")
    for e in errors:
        print(" -", e)
else:
    print("\nAll structural checks PASSED")
EOF

